from collections.abc import Sequence
from dataclasses import dataclass


@dataclass(frozen=True)
class Grammar:
    """Represents a validated Context-Free Grammar (CFG).

    Attributes:
        nonterminals: Set of nonterminal symbols (V_N).
        terminals: Set of terminal symbols (Sigma).
        start_symbol: The designated start nonterminal (S).
        productions: Dict mapping nonterminals to lists of production bodies (tuples of symbols).
                     An epsilon production is represented strictly as an empty tuple ().
    """

    nonterminals: frozenset[str]
    terminals: frozenset[str]
    start_symbol: str
    productions: dict[str, list[tuple[str, ...]]]


def build_and_validate_grammar(
    nonterminals: set[str],
    terminals: set[str],
    start_symbol: str,
    raw_productions: dict[str, Sequence[Sequence[str]]],
    epsilon_literal: str = "EPSILON",
) -> Grammar:
    """Validates and builds a Grammar instance.

    Rejection guarantees:
      1. Disjointness: Nonterminals and terminals cannot share symbols.
      2. Valid Start: Start symbol must exist within nonterminals.
      3. Defined LHS: Every production LHS must be a declared nonterminal.
      4. Complete LHS: Every nonterminal must have at least one production rule.
      5. Defined RHS Symbols: Every symbol in a RHS body must be a declared nonterminal or terminal.
      6. Unambiguous Epsilon: Epsilon cannot appear in nonterminals/terminals, and cannot be
         combined with other symbols in a RHS body (e.g., ('a', 'EPSILON') is rejected).
    """
    # 1. Nonterminal and Terminal Disjointness
    overlap = nonterminals & terminals
    if overlap:
        raise ValueError(
            f"Symbol collision: Symbols {sorted(overlap)} declared as both nonterminal and terminal."
        )

    # 2. Check epsilon literal collision in vocabulary
    if epsilon_literal in nonterminals or epsilon_literal in terminals:
        raise ValueError(
            f"Ambiguous epsilon encoding: '{epsilon_literal}' reserved for empty string "
            "but declared as a vocabulary symbol."
        )

    # 3. Valid start symbol
    if start_symbol not in nonterminals:
        raise ValueError(
            f"Undefined start symbol: '{start_symbol}' is not in declared nonterminals."
        )

    # 4. Complete LHS coverage
    missing_lhs = nonterminals - set(raw_productions.keys())
    if missing_lhs:
        raise ValueError(
            f"Missing production rules for declared nonterminals: {sorted(missing_lhs)}"
        )

    # 5. Defined LHS
    extra_lhs = set(raw_productions.keys()) - nonterminals
    if extra_lhs:
        raise ValueError(
            f"Undefined nonterminal on LHS of productions: {sorted(extra_lhs)}"
        )

    cleaned_prods: dict[str, list[tuple[str, ...]]] = {}
    all_vocab = nonterminals | terminals

    for lhs, bodies in raw_productions.items():
        if not bodies:
            raise ValueError(
                f"Nonterminal '{lhs}' has an empty list of productions."
            )

        cleaned_prods[lhs] = []
        for body in bodies:
            body_tuple = tuple(body)

            # Check for ambiguous epsilon encodings
            if epsilon_literal in body_tuple:
                if len(body_tuple) != 1:
                    raise ValueError(
                        f"Ambiguous epsilon encoding in rule {lhs} -> {body_tuple}: "
                        f"'{epsilon_literal}' cannot be combined with other symbols."
                    )
                # Valid explicit epsilon: convert to canonical empty tuple ()
                cleaned_prods[lhs].append(())
                continue

            # Standard empty sequence () is also accepted as canonical epsilon
            if len(body_tuple) == 0:
                cleaned_prods[lhs].append(())
                continue

            # Check undefined RHS symbols
            undefined_symbols = [s for s in body_tuple if s not in all_vocab]
            if undefined_symbols:
                raise ValueError(
                    f"Undefined symbol(s) {undefined_symbols} in production: {lhs} -> {body_tuple}"
                )

            cleaned_prods[lhs].append(body_tuple)

    return Grammar(
        nonterminals=frozenset(nonterminals),
        terminals=frozenset(terminals),
        start_symbol=start_symbol,
        productions=cleaned_prods,
    )


def compute_nullable(grammar: Grammar) -> frozenset[str]:
    """Computes the set of nullable nonterminals via a monotone least fixed-point iteration."""
    nullable: set[str] = set()

    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            if nt in nullable:
                continue
            for body in bodies:
                # A body derives epsilon iff all its symbols are in the current nullable set
                # For epsilon production (), all() vacuously returns True
                if all(sym in nullable for sym in body):
                    nullable.add(nt)
                    changed = True
                    break

    return frozenset(nullable)


def compute_first(
    grammar: Grammar, nullable: frozenset[str]
) -> dict[str, frozenset[str]]:
    """Computes the FIRST set for each nonterminal via a monotone least fixed-point iteration."""
    first: dict[str, set[str]] = {nt: set() for nt in grammar.nonterminals}

    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            for body in bodies:
                # Traverse body symbols left-to-right
                for sym in body:
                    if sym in grammar.terminals:
                        if sym not in first[nt]:
                            first[nt].add(sym)
                            changed = True
                        break  # Terminal stops propagation
                    else:
                        # sym is a nonterminal: propagate its FIRST set
                        sym_first = first[sym]
                        new_terminals = sym_first - first[nt]
                        if new_terminals:
                            first[nt].update(new_terminals)
                            changed = True

                        # If sym is not nullable, it blocks FIRST symbols from later symbols
                        if sym not in nullable:
                            break

    return {nt: frozenset(terms) for nt, terms in first.items()}


# =====================================================================
# Unit Tests & Independent Hand-Worked Test Cases
# =====================================================================


def test_rejection_undefined_symbol():
    """Verify rejection of undefined nonterminal in RHS."""
    try:
        build_and_validate_grammar(
            nonterminals={"S"},
            terminals={"a"},
            start_symbol="S",
            raw_productions={"S": [("a", "UNDEFINED_B")]},
        )
        assert False, "Failed to reject undefined nonterminal"
    except ValueError as e:
        assert "Undefined symbol(s)" in str(e)


def test_rejection_ambiguous_epsilon():
    """Verify rejection of epsilon combined with terminals/nonterminals."""
    try:
        build_and_validate_grammar(
            nonterminals={"S"},
            terminals={"a"},
            start_symbol="S",
            raw_productions={"S": [("a", "EPSILON")]},
        )
        assert False, "Failed to reject mixed epsilon encoding"
    except ValueError as e:
        assert "Ambiguous epsilon encoding" in str(e)


def test_handworked_case_1_indirect_nullable_chain():
    """Hand-worked Case 1: Indirect nullable chain with prefix skipping.

    Grammar:
      S -> A B c
      A -> B
      B -> EPSILON
      B -> d

    Hand derivations:
      - B -> EPSILON => B is nullable.
      - A -> B => A is nullable.
      - S -> A B c: A and B are nullable, but c is terminal => S is not nullable.
      - Nullable = {A, B}

    FIRST sets:
      - FIRST(B) = {d}
      - FIRST(A) derives B => FIRST(A) = {d}
      - FIRST(S):
          * A is first symbol: receives FIRST(A) = {d}
          * A is nullable: advances to B, receives FIRST(B) = {d}
          * B is nullable: advances to c, receives {c}
          * Total FIRST(S) = {c, d}
    """
    g = build_and_validate_grammar(
        nonterminals={"S", "A", "B"},
        terminals={"c", "d"},
        start_symbol="S",
        raw_productions={
            "S": [("A", "B", "c")],
            "A": [("B",)],
            "B": [("EPSILON",), ("d",)],
        },
    )

    null = compute_nullable(g)
    first = compute_first(g, null)

    assert null == frozenset({"A", "B"}), f"Expected Nullable {{A, B}}, got {null}"
    assert first["B"] == frozenset({"d"}), f"Expected FIRST(B) {{d}}, got {first['B']}"
    assert first["A"] == frozenset({"d"}), f"Expected FIRST(A) {{d}}, got {first['A']}"
    assert first["S"] == frozenset({"c", "d"}), (
        f"Expected FIRST(S) {{c, d}}, got {first['S']}"
    )


def test_handworked_case_2_expression_subset():
    """Hand-worked Case 2: Expression language with optional argument list.

    Grammar:
      E -> T E'
      E' -> + T E' | EPSILON
      T -> id | ( OptArgs )
      OptArgs -> Args | EPSILON
      Args -> id

    Hand derivations:
      - E' -> EPSILON => E' in Nullable.
      - OptArgs -> EPSILON => OptArgs in Nullable.
      - Nullable = {E', OptArgs}

    FIRST sets:
      - FIRST(Args) = {id}
      - FIRST(OptArgs) = FIRST(Args) = {id}
      - FIRST(T) = {id, (}
      - FIRST(E') = {+}
      - FIRST(E) = FIRST(T) = {id, (}
    """
    g = build_and_validate_grammar(
        nonterminals={"E", "E_prime", "T", "OptArgs", "Args"},
        terminals={"+", "id", "(", ")"},
        start_symbol="E",
        raw_productions={
            "E": [("T", "E_prime")],
            "E_prime": [("+", "T", "E_prime"), ("EPSILON",)],
            "T": [("id",), ("(", "OptArgs", ")")],
            "OptArgs": [("Args",), ()],  # Test empty tuple as epsilon
            "Args": [("id",)],
        },
    )

    null = compute_nullable(g)
    first = compute_first(g, null)

    assert null == frozenset({"E_prime", "OptArgs"})
    assert first["Args"] == frozenset({"id"})
    assert first["OptArgs"] == frozenset({"id"})
    assert first["T"] == frozenset({"id", "("})
    assert first["E_prime"] == frozenset({"+"})
    assert first["E"] == frozenset({"id", "("})


if __name__ == "__main__":
    test_rejection_undefined_symbol()
    test_rejection_ambiguous_epsilon()
    test_handworked_case_1_indirect_nullable_chain()
    test_handworked_case_2_expression_subset()
    print("All grammar validation, nullable, and FIRST tests passed successfully.")

