An automated grammar analyzer, conflict detector, and bounded exhaustive derivation oracle are implemented below in runnable Python to verify that:Concrete Conflict Reporting: The parsing table construction detects and reports table conflicts explicitly (differentiating FIRST/FIRST and FIRST/FOLLOW collisions with concrete witness productions), rather than resolving or selecting a production silently.Left-Recursion Detection: Direct and indirect left recursion are identified statically before table generation.Independent Bounded Oracle: An independent, non-directional exhaustive derivation generator produces all valid terminal strings up to length k, providing an unambiguous ground-truth verification oracle for accepted short strings.Complete Python Implementationfrom collections import defaultdict
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Literal


# =====================================================================
# 1. Grammar Representation and Data Structures
# =====================================================================

@dataclass(frozen=True)
class Grammar:
    nonterminals: frozenset[str]
    terminals: frozenset[str]
    start_symbol: str
    productions: dict[str, list[tuple[str, ...]]]


@dataclass(frozen=True)
class GrammarConflict:
    nonterminal: str
    lookahead: str
    conflict_type: Literal["FIRST/FIRST", "FIRST/FOLLOW"]
    production_a: tuple[str, ...]
    production_b: tuple[str, ...]

    def __str__(self) -> str:
        prod_a_str = " ".join(self.production_a) if self.production_a else "ε"
        prod_b_str = " ".join(self.production_b) if self.production_b else "ε"
        return (
            f"[{self.conflict_type} Conflict on table entry M[{self.nonterminal}, '{self.lookahead}']]:\n"
            f"  Production 1: {self.nonterminal} -> {prod_a_str}\n"
            f"  Production 2: {self.nonterminal} -> {prod_b_str}"
        )


class GrammarAnalysisError(Exception):
    def __init__(self, message: str, conflicts: list[GrammarConflict] | None = None):
        super().__init__(message)
        self.conflicts = conflicts or []


# =====================================================================
# 2. Grammar Validation and Static Checks
# =====================================================================

def build_grammar(
    nonterminals: set[str],
    terminals: set[str],
    start_symbol: str,
    raw_productions: dict[str, Sequence[Sequence[str]]],
    epsilon_literal: str = "EPSILON",
    endmarker_literal: str = "$",
) -> Grammar:
    if endmarker_literal in nonterminals or endmarker_literal in terminals:
        raise ValueError(f"Endmarker token '{endmarker_literal}' is reserved.")

    overlap = nonterminals & terminals
    if overlap:
        raise ValueError(f"Nonterminal and terminal overlap: {sorted(overlap)}")

    if start_symbol not in nonterminals:
        raise ValueError(f"Start symbol '{start_symbol}' not in declared nonterminals.")

    cleaned: dict[str, list[tuple[str, ...]]] = {}
    all_vocab = nonterminals | terminals

    for lhs, bodies in raw_productions.items():
        if lhs not in nonterminals:
            raise ValueError(f"LHS nonterminal '{lhs}' is not declared.")
        cleaned[lhs] = []
        for body in bodies:
            body_tuple = tuple(body)
            if epsilon_literal in body_tuple:
                if len(body_tuple) != 1:
                    raise ValueError(f"Ambiguous mixed epsilon body: {lhs} -> {body_tuple}")
                cleaned[lhs].append(())
                continue
            if len(body_tuple) == 0:
                cleaned[lhs].append(())
                continue

            undefined = [s for s in body_tuple if s not in all_vocab]
            if undefined:
                raise ValueError(f"Undefined symbol(s) {undefined} in {lhs} -> {body_tuple}")
            cleaned[lhs].append(body_tuple)

    return Grammar(
        nonterminals=frozenset(nonterminals),
        terminals=frozenset(terminals),
        start_symbol=start_symbol,
        productions=cleaned,
    )


def detect_left_recursion(grammar: Grammar) -> list[str]:
    """Detects direct and indirect left recursion using transitive closure."""
    nullable = compute_nullable(grammar)

    # Directed edge A -> B if A -> B ... or A -> N_1 ... N_k B ... where N_i in nullable
    direct_left_graph: dict[str, set[str]] = defaultdict(set)
    for lhs, bodies in grammar.productions.items():
        for body in bodies:
            for sym in body:
                if sym in grammar.nonterminals:
                    direct_left_graph[lhs].add(sym)
                if sym not in nullable:
                    break

    # Transitive closure (Warshall / DFS)
    reachability: dict[str, set[str]] = {nt: set(targets) for nt, targets in direct_left_graph.items()}
    for k in grammar.nonterminals:
        for i in grammar.nonterminals:
            if k in reachability.get(i, set()):
                reachability[i].update(reachability.get(k, set()))

    left_recursive = []
    for nt in sorted(grammar.nonterminals):
        if nt in reachability.get(nt, set()):
            left_recursive.append(nt)

    return left_recursive


# =====================================================================
# 3. Monotone Fixed-Point Nullable, FIRST, and FOLLOW
# =====================================================================

def compute_nullable(grammar: Grammar) -> frozenset[str]:
    nullable: set[str] = set()
    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            if nt in nullable:
                continue
            for body in bodies:
                if all(sym in nullable for sym in body):
                    nullable.add(nt)
                    changed = True
                    break
    return frozenset(nullable)


def compute_first(
    grammar: Grammar, nullable: frozenset[str]
) -> dict[str, frozenset[str]]:
    first: dict[str, set[str]] = {nt: set() for nt in grammar.nonterminals}
    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            for body in bodies:
                for sym in body:
                    if sym in grammar.terminals:
                        if sym not in first[nt]:
                            first[nt].add(sym)
                            changed = True
                        break
                    else:
                        diff = first[sym] - first[nt]
                        if diff:
                            first[nt].update(diff)
                            changed = True
                        if sym not in nullable:
                            break
    return {nt: frozenset(s) for nt, s in first.items()}


def compute_sequence_first(
    seq: Sequence[str],
    grammar: Grammar,
    nullable: frozenset[str],
    first: dict[str, frozenset[str]],
) -> tuple[frozenset[str], bool]:
    res: set[str] = set()
    for sym in seq:
        if sym in grammar.terminals:
            res.add(sym)
            return frozenset(res), False
        else:
            res.update(first[sym])
            if sym not in nullable:
                return frozenset(res), False
    return frozenset(res), True


def compute_follow(
    grammar: Grammar,
    nullable: frozenset[str],
    first: dict[str, frozenset[str]],
    endmarker: str = "$",
) -> dict[str, frozenset[str]]:
    follow: dict[str, set[str]] = {nt: set() for nt in grammar.nonterminals}
    follow[grammar.start_symbol].add(endmarker)

    changed = True
    while changed:
        changed = False
        for lhs, bodies in grammar.productions.items():
            for body in bodies:
                for i, sym in enumerate(body):
                    if sym not in grammar.nonterminals:
                        continue
                    suffix = body[i + 1 :]
                    suffix_first, suffix_is_nullable = compute_sequence_first(
                        suffix, grammar, nullable, first
                    )
                    new_terms = suffix_first - follow[sym]
                    if new_terms:
                        follow[sym].update(new_terms)
                        changed = True
                    if suffix_is_nullable:
                        diff = follow[lhs] - follow[sym]
                        if diff:
                            follow[sym].update(diff)
                            changed = True

    return {nt: frozenset(s) for nt, s in follow.items()}


# =====================================================================
# 4. Conflict-Reporting Table Generator
# =====================================================================

def construct_predictive_table_with_audit(
    grammar: Grammar,
    endmarker: str = "$",
) -> tuple[dict[tuple[str, str], tuple[str, ...]], list[GrammarConflict]]:
    """Builds an LL(1) table while capturing and reporting every conflict.

    Never chooses a production silently when a collision occurs.
    """
    left_recursive_nts = detect_left_recursion(grammar)
    if left_recursive_nts:
        raise GrammarAnalysisError(
            f"Static Analysis Failed: Grammar contains left-recursive nonterminal(s): {left_recursive_nts}."
        )

    nullable = compute_nullable(grammar)
    first = compute_first(grammar, nullable)
    follow = compute_follow(grammar, nullable, first, endmarker=endmarker)

    # Multi-map tracking all candidate productions per cell
    raw_table: dict[tuple[str, str], list[tuple[str, ...]]] = defaultdict(list)
    conflicts: list[GrammarConflict] = []

    for lhs, bodies in grammar.productions.items():
        for body in bodies:
            body_first, is_nullable = compute_sequence_first(body, grammar, nullable, first)
            for a in body_first:
                raw_table[(lhs, a)].append(body)
            if is_nullable:
                for b in follow[lhs]:
                    if body not in raw_table[(lhs, b)]:
                        raw_table[(lhs, b)].append(body)

    # Conflict Audit Phase
    deterministic_table: dict[tuple[str, str], tuple[str, ...]] = {}
    for (nt, lookahead), candidate_prods in raw_table.items():
        if len(candidate_prods) > 1:
            prod_a = candidate_prods[0]
            prod_b = candidate_prods[1]

            # Distinguish FIRST/FIRST from FIRST/FOLLOW
            prod_a_first, prod_a_null = compute_sequence_first(prod_a, grammar, nullable, first)
            prod_b_first, prod_b_null = compute_sequence_first(prod_b, grammar, nullable, first)

            if lookahead in prod_a_first and lookahead in prod_b_first:
                conflict_type = "FIRST/FIRST"
            else:
                conflict_type = "FIRST/FOLLOW"

            conflicts.append(
                GrammarConflict(
                    nonterminal=nt,
                    lookahead=lookahead,
                    conflict_type=conflict_type,
                    production_a=prod_a,
                    production_b=prod_b,
                )
            )
        else:
            deterministic_table[(nt, lookahead)] = candidate_prods[0]

    return deterministic_table, conflicts


# =====================================================================
# 5. Independent Bounded Exhaustive Derivation Oracle
# =====================================================================

def bounded_exhaustive_derivation_oracle(
    grammar: Grammar,
    max_length: int,
    max_depth: int = 20,
) -> set[tuple[str, ...]]:
    """Generates the exact set of terminal strings of length <= max_length

    derived from grammar.start_symbol via breadth-first / exhaustive expansion.
    Operates independently of LL(1) parse tables, directions, or constraints.
    """
    accepted_strings: set[tuple[str, ...]] = set()
    queue: list[tuple[tuple[str, ...], int]] = [((grammar.start_symbol,), 0)]
    seen_sentential: set[tuple[str, ...]] = { (grammar.start_symbol,) }

    while queue:
        sentential, depth = queue.pop(0)

        # Terminal count lower bound: terminals already in sentential form
        terminal_count = sum(1 for sym in sentential if sym in grammar.terminals)
        if terminal_count > max_length or depth > max_depth:
            continue

        # If fully resolved to terminals
        if all(sym in grammar.terminals for sym in sentential):
            if len(sentential) <= max_length:
                accepted_strings.add(sentential)
            continue

        # Find the leftmost nonterminal
        for idx, sym in enumerate(sentential):
            if sym in grammar.nonterminals:
                leftmost_idx = idx
                nt = sym
                break
        else:
            continue

        # Expand leftmost nonterminal across all its production alternatives
        prefix = sentential[:leftmost_idx]
        suffix = sentential[leftmost_idx + 1 :]
        for body in grammar.productions[nt]:
            next_sentential = prefix + body + suffix
            # Only enqueue if within terminal length bounds
            if sum(1 for s in next_sentential if s in grammar.terminals) <= max_length:
                if next_sentential not in seen_sentential:
                    seen_sentential.add(next_sentential)
                    queue.append((next_sentential, depth + 1))

    return accepted_strings


