# 6. Verification and Demonstration Suite
# =====================================================================

def test_left_recursive_rejection():
    print("\n" + "=" * 70)
    print("TEST 1: Left-Recursive Grammar Detection")
    print("=" * 70)
    # Direct left recursion: E -> E + T | T
    raw_prods = {
        "E": [("E", "+", "T"), ("T",)],
        "T": [("id",)],
    }
    g = build_grammar(
        nonterminals={"E", "T"},
        terminals={"+", "id"},
        start_symbol="E",
        raw_productions=raw_prods,
    )
    try:
        construct_predictive_table_with_audit(g)
        assert False, "Failed to reject left-recursive grammar."
    except GrammarAnalysisError as e:
        print("[Pass] Static analyzer successfully halted before table generation:")
        print(f"       {e}")


def test_deliberate_conflicts_reporting():
    print("\n" + "=" * 70)
    print("TEST 2: Deliberate Conflicts Audit (No Silent Selection)")
    print("=" * 70)
    # Introducing:
    # 1. FIRST/FIRST conflict: S -> a A | a B
    # 2. FIRST/FOLLOW conflict: A -> a | EPSILON with FOLLOW(A) containing 'a'
    raw_prods = {
        "S": [("a", "A"), ("a", "B")],  # FIRST/FIRST on 'a'
        "A": [("a",), ()],              # FIRST/FOLLOW on 'a'
        "B": [("b",)],
    }
    g = build_grammar(
        nonterminals={"S", "A", "B"},
        terminals={"a", "b"},
        start_symbol="S",
        raw_productions=raw_prods,
    )

    _, conflicts = construct_predictive_table_with_audit(g)
    print(f"[Pass] Analyzer detected {len(conflicts)} concrete conflict(s) without silent selection:\n")
    for idx, c in enumerate(conflicts, 1):
        print(f"Conflict #{idx}:")
        print(c)
        print("-" * 50)

    # Assert specific conflicts exist
    assert any(c.conflict_type == "FIRST/FIRST" and c.lookahead == "a" and c.nonterminal == "S" for c in conflicts)
    assert any(c.conflict_type == "FIRST/FOLLOW" and c.lookahead == "a" and c.nonterminal == "A" for c in conflicts)


def test_independent_oracle_validation():
    print("\n" + "=" * 70)
    print("TEST 3: Independent Exhaustive Oracle Validation")
    print("=" * 70)
    # Deterministic LL(1) grammar for arithmetic expressions with parentheses
    raw_prods = {
        "E": [("T", "E_prime")],
        "E_prime": [("+", "T", "E_prime"), ()],
        "T": [("id",), ("(", "E", ")")],
    }
    g = build_grammar(
        nonterminals={"E", "E_prime", "T"},
        terminals={"id", "+", "(", ")"},
        start_symbol="E",
        raw_productions=raw_prods,
    )

    table, conflicts = construct_predictive_table_with_audit(g)
    assert len(conflicts) == 0, f"Expected clean LL(1) grammar, got conflicts: {conflicts}"

    # Generate reference ground-truth terminal strings up to length 5
    oracle_strings = bounded_exhaustive_derivation_oracle(g, max_length=5, max_depth=12)
    oracle_formatted = sorted([" ".join(s) if s else "ε" for s in oracle_strings])

    print(f"[Pass] Independent derivation oracle generated {len(oracle_strings)} valid strings (length <= 5):")
    for s in oracle_formatted:
        print(f"       - {s}")

    # Verify that each oracle string is syntactically consistent
    assert "id" in oracle_formatted
    assert "id + id" in oracle_formatted
    assert "( id )" in oracle_formatted
    assert "id + id + id" in oracle_formatted
    assert "( ( id ) )" in oracle_formatted
    assert "( id + id )" in oracle_formatted


