"""Complete, self-contained reference implementation for LL(1) grammar analysis,

table construction, predictive parsing with ASCII tree output, and oracle
validation.
Standard Library only. Python 3.10+ compatible.
"""

from collections import defaultdict
from collections.abc import Sequence
from dataclasses import dataclass, field
from typing import Literal


# =====================================================================
# 1. Grammar Representation and Data Structures
# =====================================================================


@dataclass(frozen=True)
class Grammar:
    nonterminals: frozenset[str]
    terminals: frozenset[str]
    start_symbol: str
    productions: dict[str, list[tuple[str, ...]]]


@dataclass(frozen=True)
class GrammarConflict:
    nonterminal: str
    lookahead: str
    conflict_type: Literal["FIRST/FIRST", "FIRST/FOLLOW"]
    production_a: tuple[str, ...]
    production_b: tuple[str, ...]

    def __str__(self) -> str:
        pa = " ".join(self.production_a) if self.production_a else "ε"
        pb = " ".join(self.production_b) if self.production_b else "ε"
        return (
            f"[{self.conflict_type} Conflict at M[{self.nonterminal}, '{self.lookahead}']]:\n"
            f"  Alt 1: {self.nonterminal} -> {pa}\n"
            f"  Alt 2: {self.nonterminal} -> {pb}"
        )


class GrammarAnalysisError(Exception):

    def __init__(
        self, message: str, conflicts: list[GrammarConflict] | None = None
    ):
        super().__init__(message)
        self.conflicts = conflicts or []


# =====================================================================
# 2. Grammar Validation and Static Cycle Analysis
# =====================================================================


def build_and_validate_grammar(
    nonterminals: set[str],
    terminals: set[str],
    start_symbol: str,
    raw_productions: dict[str, Sequence[Sequence[str]]],
    epsilon_literal: str = "EPSILON",
    endmarker_literal: str = "$",
) -> Grammar:
    if endmarker_literal in nonterminals or endmarker_literal in terminals:
        raise ValueError(
            f"Reserved endmarker '{endmarker_literal}' collision."
        )
    overlap = nonterminals & terminals
    if overlap:
        raise ValueError(f"Symbol collision: {sorted(overlap)}")
    if start_symbol not in nonterminals:
        raise ValueError(f"Start symbol '{start_symbol}' is not a nonterminal.")

    all_vocab = nonterminals | terminals
    cleaned: dict[str, list[tuple[str, ...]]] = {}

    for lhs, bodies in raw_productions.items():
        if lhs not in nonterminals:
            raise ValueError(f"LHS '{lhs}' not in nonterminals.")
        cleaned[lhs] = []
        for body in bodies:
            bt = tuple(body)
            if epsilon_literal in bt:
                if len(bt) != 1:
                    raise ValueError(
                        f"Mixed epsilon encoding in {lhs} -> {bt}"
                    )
                cleaned[lhs].append(())
                continue
            if len(bt) == 0:
                cleaned[lhs].append(())
                continue
            undef = [s for s in bt if s not in all_vocab]
            if undef:
                raise ValueError(
                    f"Undefined symbol(s) {undef} in {lhs} -> {bt}"
                )
            cleaned[lhs].append(bt)

    return Grammar(
        nonterminals=frozenset(nonterminals),
        terminals=frozenset(terminals),
        start_symbol=start_symbol,
        productions=cleaned,
    )


def detect_left_recursion(grammar: Grammar) -> list[str]:
    nullable = compute_nullable(grammar)
    direct_graph: dict[str, set[str]] = defaultdict(set)
    for lhs, bodies in grammar.productions.items():
        for body in bodies:
            for sym in body:
                if sym in grammar.nonterminals:
                    direct_graph[lhs].add(sym)
                if sym not in nullable:
                    break

    reach: dict[str, set[str]] = {
        nt: set(targets) for nt, targets in direct_graph.items()
    }
    for k in grammar.nonterminals:
        for i in grammar.nonterminals:
            if k in reach.get(i, set()):
                reach[i].update(reach.get(k, set()))

    return [nt for nt in sorted(grammar.nonterminals) if nt in reach.get(nt, set())]


# =====================================================================
# 3. Fixed-Point Math Engine
# =====================================================================


def compute_nullable(grammar: Grammar) -> frozenset[str]:
    nullable: set[str] = set()
    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            if nt in nullable:
                continue
            for body in bodies:
                if all(sym in nullable for sym in body):
                    nullable.add(nt)
                    changed = True
                    break
    return frozenset(nullable)


def compute_first(
    grammar: Grammar, nullable: frozenset[str]
) -> dict[str, frozenset[str]]:
    first: dict[str, set[str]] = {nt: set() for nt in grammar.nonterminals}
    changed = True
    while changed:
        changed = False
        for nt, bodies in grammar.productions.items():
            for body in bodies:
                for sym in body:
                    if sym in grammar.terminals:
                        if sym not in first[nt]:
                            first[nt].add(sym)
                            changed = True
                        break
                    else:
                        diff = first[sym] - first[nt]
                        if diff:
                            first[nt].update(diff)
                            changed = True
                        if sym not in nullable:
                            break
    return {nt: frozenset(s) for nt, s in first.items()}


def compute_sequence_first(
    seq: Sequence[str],
    grammar: Grammar,
    nullable: frozenset[str],
    first: dict[str, frozenset[str]],
) -> tuple[frozenset[str], bool]:
    res: set[str] = set()
    for sym in seq:
        if sym in grammar.terminals:
            res.add(sym)
            return frozenset(res), False
        else:
            res.update(first[sym])
            if sym not in nullable:
                return frozenset(res), False
    return frozenset(res), True


def compute_follow(
    grammar: Grammar,
    nullable: frozenset[str],
    first: dict[str, frozenset[str]],
    endmarker: str = "$",
) -> dict[str, frozenset[str]]:
    follow: dict[str, set[str]] = {nt: set() for nt in grammar.nonterminals}
    follow[grammar.start_symbol].add(endmarker)

    changed = True
    while changed:
        changed = False
        for lhs, bodies in grammar.productions.items():
            for body in bodies:
                for i, sym in enumerate(body):
                    if sym not in grammar.nonterminals:
                        continue
                    suffix = body[i + 1 :]
                    suffix_first, suffix_null = compute_sequence_first(
                        suffix, grammar, nullable, first
                    )
                    new_terms = suffix_first - follow[sym]
                    if new_terms:
                        follow[sym].update(new_terms)
                        changed = True
                    if suffix_null:
                        diff = follow[lhs] - follow[sym]
                        if diff:
                            follow[sym].update(diff)
                            changed = True
    return {nt: frozenset(s) for nt, s in follow.items()}


def construct_table_with_audit(
    grammar: Grammar, endmarker: str = "$"
) -> tuple[dict[tuple[str, str], tuple[str, ...]], list[GrammarConflict]]:
    lr = detect_left_recursion(grammar)
    if lr:
        raise GrammarAnalysisError(
            f"Grammar contains left-recursive nonterminal(s): {lr}"
        )

    nullable = compute_nullable(grammar)
    first = compute_first(grammar, nullable)
    follow = compute_follow(grammar, nullable, first, endmarker=endmarker)

    raw_table: dict[tuple[str, str], list[tuple[str, ...]]] = defaultdict(list)
    conflicts: list[GrammarConflict] = []

    for lhs, bodies in grammar.productions.items():
        for body in bodies:
            body_first, is_nullable = compute_sequence_first(
                body, grammar, nullable, first
            )
            for a in body_first:
                raw_table[(lhs, a)].append(body)
            if is_nullable:
                for b in follow[lhs]:
                    if body not in raw_table[(lhs, b)]:
                        raw_table[(lhs, b)].append(body)

    deterministic_table: dict[tuple[str, str], tuple[str, ...]] = {}
    for (nt, lookahead), candidates in raw_table.items():
        if len(candidates) > 1:
            p_a, p_b = candidates[0], candidates[1]
            fa, _ = compute_sequence_first(p_a, grammar, nullable, first)
            fb, _ = compute_sequence_first(p_b, grammar, nullable, first)
            c_type = (
                "FIRST/FIRST"
                if (lookahead in fa and lookahead in fb)
                else "FIRST/FOLLOW"
            )
            conflicts.append(
                GrammarConflict(nt, lookahead, c_type, p_a, p_b)
            )
        else:
            deterministic_table[(nt, lookahead)] = candidates[0]

    return deterministic_table, conflicts


# =====================================================================
# 4. AST / Parse Tree Node and Predictive Parser
# =====================================================================


@dataclass
class ParseTreeNode:
    symbol: str
    children: list["ParseTreeNode"] = field(default_factory=list)

    def to_ascii(self, prefix: str = "", is_last: bool = True) -> str:
        branch = "└── " if is_last else "├── "
        res = prefix + branch + self.symbol + "\n"
        new_prefix = prefix + ("    " if is_last else "│   ")
        for i, child in enumerate(self.children):
            res += child.to_ascii(new_prefix, i == len(self.children) - 1)
        return res


@dataclass
class ParserOutput:
    success: bool
    parse_tree: ParseTreeNode | None = None
    step_count: int = 0
    error_msg: str | None = None


class PredictiveLL1Parser:

    def __init__(
        self,
        table: dict[tuple[str, str], tuple[str, ...]],
        grammar: Grammar,
        endmarker: str = "$",
        max_steps: int = 500,
    ):
        self.table = table
        self.grammar = grammar
        self.endmarker = endmarker
        self.max_steps = max_steps

    def parse(self, tokens: list[str]) -> ParserOutput:
        input_stream = list(tokens) + [self.endmarker]
        root_node = ParseTreeNode(self.grammar.start_symbol)

        # The stack holds: (symbol, corresponding_tree_node)
        stack: list[tuple[str, ParseTreeNode | None]] = [
            (self.endmarker, None),
            (self.grammar.start_symbol, root_node),
        ]

        cursor = 0
        steps = 0
        nonterminal_expansions_since_consume = 0

        while stack:
            steps += 1
            lookahead = input_stream[cursor]

            # Bounded empirical trace check
            if steps > self.max_steps:
                return ParserOutput(
                    False,
                    step_count=steps,
                    error_msg=f"Trace limit exceeded ({self.max_steps} steps).",
                )

            top_sym, top_node = stack[-1]

            # Lexical sanity
            if (
                lookahead not in self.grammar.terminals
                and lookahead != self.endmarker
            ):
                return ParserOutput(
                    False,
                    step_count=steps,
                    error_msg=f"Lexical error: Unexpected token '{lookahead}'.",
                )

            # End of input reached
            if top_sym == self.endmarker and lookahead == self.endmarker:
                stack.pop()
                return ParserOutput(
                    True, parse_tree=root_node, step_count=steps
                )

            # Top of stack is terminal
            if (
                top_sym in self.grammar.terminals
                or top_sym == self.endmarker
            ):
                if top_sym == lookahead:
                    stack.pop()
                    cursor += 1
                    nonterminal_expansions_since_consume = 0
                else:
                    return ParserOutput(
                        False,
                        step_count=steps,
                        error_msg=f"Terminal mismatch: Expected '{top_sym}', got '{lookahead}'.",
                    )

            # Top of stack is nonterminal
            elif top_sym in self.grammar.nonterminals:
                key = (top_sym, lookahead)
                if key not in self.table:
                    return ParserOutput(
                        False,
                        step_count=steps,
                        error_msg=f"Syntax error: No transition for [{top_sym}, '{lookahead}'].",
                    )

                production = self.table[key]
                stack.pop()
                nonterminal_expansions_since_consume += 1

                if nonterminal_expansions_since_consume > len(
                    self.grammar.nonterminals
                ):
                    return ParserOutput(
                        False,
                        step_count=steps,
                        error_msg="Runaway expansion loop detected.",
                    )

                if production == ():
                    # Epsilon leaf
                    if top_node:
                        top_node.children.append(ParseTreeNode("ε"))
                else:
                    # Allocate child nodes and push in reverse order
                    child_nodes = [ParseTreeNode(s) for s in production]
                    if top_node:
                        top_node.children.extend(child_nodes)
                    for s, node in reversed(list(zip(production, child_nodes))):
                        stack.append((s, node))

        return ParserOutput(
            False,
            step_count=steps,
            error_msg="Stack exhausted unexpectedly.",
        )


# =====================================================================
# 5. Independent Bounded Exhaustive Derivation Oracle
# =====================================================================


def bounded_derivation_oracle(
    grammar: Grammar, max_length: int, max_depth: int = 15
) -> set[tuple[str, ...]]:
    accepted: set[tuple[str, ...]] = set()
    queue: list[tuple[tuple[str, ...], int]] = [((grammar.start_symbol,), 0)]
    seen: set[tuple[str, ...]] = { (grammar.start_symbol,) }

    while queue:
        sentential, depth = queue.pop(0)
        t_count = sum(1 for s in sentential if s in grammar.terminals)
        if t_count > max_length or depth > max_depth:
            continue

        if all(s in grammar.terminals for s in sentential):
            if len(sentential) <= max_length:
                accepted.add(sentential)
            continue

        for i, sym in enumerate(sentential):
            if sym in grammar.nonterminals:
                prefix = sentential[:i]
                suffix = sentential[i + 1 :]
                for body in grammar.productions[sym]:
                    nxt = prefix + body + suffix
                    if (
                        sum(1 for s in nxt if s in grammar.terminals)
                        <= max_length
                        and nxt not in seen
                    ):
                        seen.add(nxt)
                        queue.append((nxt, depth + 1))
                break
    return accepted


