def power_mod(base: int, exponent: int, modulus: int) -> int:
    if not isinstance(base, int) or isinstance(base, bool):
        raise TypeError("base must be an integer.")
    if not isinstance(exponent, int) or isinstance(exponent, bool):
        raise TypeError("exponent must be an integer.")
    if not isinstance(modulus, int) or isinstance(modulus, bool):
        raise TypeError("modulus must be an integer.")
    if modulus <= 1:
        raise ValueError(f"Modulus must be an integer strictly greater than 1, got {modulus}.")

    if exponent < 0:
        base = mod_inverse(base, modulus)
        exponent = -exponent

    result = 1
    cur = base % modulus
    exp = exponent
    while exp > 0:
        if exp & 1:
            result = (result * cur) % modulus
        cur = (cur * cur) % modulus
        exp >>= 1
    return result

print("power_mod(7, 3, 187) =", power_mod(7, 3, 187))
print("power_mod(156, 107, 187) =", power_mod(156, 107, 187))
print("power_mod(3, -1, 160) =", power_mod(3, -1, 160))
